import{_ as e,o as d,c as r,a2 as a}from"./chunks/framework.Bg-Zxr5O.js";const b=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/Matrix-Index-Operator.md","filePath":"manual-en/Matrix-Index-Operator.md","lastUpdated":1785684581000}'),n={name:"manual-en/Matrix-Index-Operator.md"};function o(h,t,i,s,l,p){return d(),r("div",null,[...t[0]||(t[0]=[a('<h4 id="_16-4-1-3-index-operator" tabindex="-1">16.4.1.3 Index Operator <code>()</code> <a class="header-anchor" href="#_16-4-1-3-index-operator" aria-label="Permalink to &quot;16.4.1.3 Index Operator `()`&quot;">​</a></h4><p>The result of the submatrix or indexing operator, written <code>m(rindex, cindex)</code>, contains the rows of m whose indexes are given in vector rindex and the columns whose indexes are given in vector cindex.</p><p>In the simplest case, if rindex and cindex are both scalars, the result is also a scalar:</p><table tabindex="0"><thead><tr><th>{10, 20; 30, 40}(1, 1)</th><th>⇒</th><th>10</th></tr></thead><tbody><tr><td>{10, 20; 30, 40}(1, 2)</td><td>⇒</td><td>20</td></tr><tr><td>{10, 20; 30, 40}(2, 1)</td><td>⇒</td><td>30</td></tr><tr><td>{10, 20; 30, 40}(2, 2)</td><td>⇒</td><td>40</td></tr></tbody></table><p>If the index arguments have multiple elements, then the result includes multiple rows or columns:</p><table tabindex="0"><thead><tr><th>{10, 20; 30, 40}(1:2, 1)</th><th>⇒</th><th>{10; 30}</th></tr></thead><tbody><tr><td>{10, 20; 30, 40}(2, 1:2)</td><td>⇒</td><td>{30, 40}</td></tr><tr><td>{10, 20; 30, 40}(1:2, 1:2)</td><td>⇒</td><td>{10, 20; 30, 40}</td></tr></tbody></table><p>The special argument ‘:’ may stand in for all the rows or columns in the matrix being indexed, like this:</p><table tabindex="0"><thead><tr><th>{10, 20; 30, 40}(:, 1)</th><th>⇒</th><th>{10; 30}</th></tr></thead><tbody><tr><td>{10, 20; 30, 40}(2, 😃</td><td>⇒</td><td>{30, 40}</td></tr><tr><td>{10, 20; 30, 40}(:, 😃</td><td>⇒</td><td>{10, 20; 30, 40}</td></tr></tbody></table><p>The index arguments do not have to be in order, and they may contain repeated values, like this:</p><table tabindex="0"><thead><tr><th>{10, 20; 30, 40}({2, 1}, 1)</th><th>⇒</th><th>{30; 10}</th></tr></thead><tbody><tr><td>{10, 20; 30, 40}(2, {2; 2; 1})</td><td>⇒</td><td>{40, 40, 30}</td></tr><tr><td>{10, 20; 30, 40}(2:1:-1, 😃</td><td>⇒</td><td>{30, 40; 10, 20}</td></tr></tbody></table><p>When the matrix being indexed is a row or column vector, only a single index argument is needed, like this:</p><table tabindex="0"><thead><tr><th>{11, 12, 13, 14, 15}(2:4)</th><th>⇒</th><th>{12, 13, 14}</th></tr></thead><tbody><tr><td>{11; 12; 13; 14; 15}(2:4)</td><td>⇒</td><td>{12; 13; 14}</td></tr></tbody></table><p>When an index is not an integer, PSPP discards the fractional part. It is an error for an index to be less than 1 or greater than the number of rows or columns:</p><table tabindex="0"><thead><tr><th>{11, 12, 13, 14}({2.5, 4.6})</th><th>⇒</th><th>{12, 14}</th></tr></thead><tbody><tr><td>{11; 12; 13; 14}(0)</td><td>⇒</td><td>(error)</td></tr></tbody></table>',14)])])}const c=e(n,[["render",o]]);export{b as __pageData,c as default};
